// fwdTxfm4x8RVV is the 4x8 DCT_DCT forward transform. There is no lane shuffle
// in RVV, so the transpose is a contiguous store followed by strided loads.
TEXT ·fwdTxfm4x8RVV(SB), NOSPLIT, $128-40
	MOV  res+0(FP), X10
	MOV  src+8(FP), X11
	MOV  srcStride+16(FP), X12
	SLLI $2, X12, X12
	MOV  $4, X13
	VSETVLI X13, E32, M1, TA, MA, X5

	VLE32V (X11), V0
	ADD    X12, X11, X14
	VLE32V (X14), V1
	ADD    X12, X14, X14
	VLE32V (X14), V2
	ADD    X12, X14, X14
	VLE32V (X14), V3
	ADD    X12, X14, X14
	VLE32V (X14), V4
	ADD    X12, X14, X14
	VLE32V (X14), V5
	ADD    X12, X14, X14
	VLE32V (X14), V6
	ADD    X12, X14, X14
	VLE32V (X14), V7
	VSLLVI $2, V0, V0
	VSLLVI $2, V1, V1
	VSLLVI $2, V2, V2
	VSLLVI $2, V3, V3
	VSLLVI $2, V4, V4
	VSLLVI $2, V5, V5
	VSLLVI $2, V6, V6
	VSLLVI $2, V7, V7

	DCT8CR
	MOV  colAdst+24(FP), X5
	BNEZ X5, r48ca
	FDCT8R(V0, V1, V2, V3, V4, V5, V6, V7)
	JMP  r48cd

r48ca:
	FADST8R

r48cd:

	MOV    $scratch-128(SP), X14
	VSE32V V0, (X14)
	ADD    $16, X14, X15
	VSE32V V1, (X15)
	ADD    $16, X15, X15
	VSE32V V2, (X15)
	ADD    $16, X15, X15
	VSE32V V3, (X15)
	ADD    $16, X15, X15
	VSE32V V4, (X15)
	ADD    $16, X15, X15
	VSE32V V5, (X15)
	ADD    $16, X15, X15
	VSE32V V6, (X15)
	ADD    $16, X15, X15
	VSE32V V7, (X15)

	MOV $8, X13
	VSETVLI X13, E32, M1, TA, MA, X5
	MOV     $16, X16
	VLSE32V (X14), X16, V0
	ADD     $4, X14, X15
	VLSE32V (X15), X16, V1
	ADD     $4, X15, X15
	VLSE32V (X15), X16, V2
	ADD     $4, X15, X15
	VLSE32V (X15), X16, V3

	MOV  rowAdst+32(FP), X5
	BNEZ X5, r48ra
	DCTCR
	FDCT4R(V0, V1, V2, V3)
	JMP  r48rd

r48ra:
	ADSTCR
	FADST4R(V0, V1, V2, V3)

r48rd:

	RECTCR
	RECT1R(V0)
	RECT1R(V1)
	RECT1R(V2)
	RECT1R(V3)

	VSE32V V0, (X10)
	ADD    $32, X10, X15
	VSE32V V1, (X15)
	ADD    $32, X15, X15
	VSE32V V2, (X15)
	ADD    $32, X15, X15
	VSE32V V3, (X15)
	RET

